int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_association *asoc;
    struct sctp_assoc_stats stats;
    int ret = 0;

    if (len < sizeof(stats))
        return -EINVAL;

    asoc = sctp_id2assoc(sk, 0);
    if (!asoc)
        return -ENOENT;

    memset(&stats, 0, sizeof(stats));
    stats.assoc_id = asoc->assoc_id;
    stats.cumu_flightsize = asoc->c.sacks;
    stats.adaptation_ind = asoc->adaptation_ind;
    stats.since_last_t3 = asoc->since_last_t3;

    stats.max_rto = jiffies_to_msecs(asoc->rto_max);
    stats.a_rto = jiffies_to_msecs(asoc->rto);
    stats.rtt = jiffies_to_msecs(asoc->rtt);
    stats.min_rtt = jiffies_to_msecs(asoc->rtt_min);

    if (copy_to_user(optval, &stats, sizeof(stats)) != 0)
        return -EFAULT;

    if (optlen && put_user(sizeof(stats), optlen) != 0)
        return -EFAULT;

    return 0;
}

