    stats.outbound_bytes = htonl(asoc->outbound_bytes);
    stats.inbound_packets = htonl(asoc->inbound_packets);
    stats.outbound_packets = htonl(asoc->outbound_packets);

    stats.inbound_data_pkts = htonl(asoc->inbound_data_pkts);
    stats.outbound_data_pkts = htonl(asoc->outbound_data_pkts);

    stats.retransmits = htonl(asoc->retransmits);
    stats.timeouts = htonl(asoc->timeouts);

    stats.max_rto = htonl(asoc->rto_max);

    if (copy_to_user(optval, &stats, sizeof(stats)))
        return -EFAULT;

    if (put_user(sizeof(stats), optlen))
        return -EFAULT;

    return 0;
}

